export function t(key) {
  const e = I18N[key];
  if (!e) return key;
  return e[settings.lang] || e.fr || key;
}

// Template avec variables : tf('key', {n:3}) remplace {n} dans la chaîne traduite
export function tf(key, vars) {
  return t(key).replace(/\{(\w+)\}/g, (_, k) => (vars && vars[k] != null) ? vars[k] : '');
}

// Pluriel : la valeur du dico est [singulier, pluriel] par langue
export function tPlural(key, n) {
  const e = I18N[key];
  const arr = (e && (e[settings.lang] || e.fr)) || [key, key];
  return arr[n > 1 ? 1 : 0];
}

// Locale BCP-47 dérivée de la langue de l'app (pour Intl / toLocaleDateString)
export function localeApp() {
  return { fr:'fr-BE', nl:'nl-BE', en:'en-GB', de:'de-BE' }[settings.lang] || 'fr-BE';
}
// Jour de semaine abrégé localisé (« Mar. » / « di » / « Tue ») + majuscule initiale
export function nomJourCourt(dateObj) {
  const s = dateObj.toLocaleDateString(localeApp(), { weekday: 'short' });
  return s.charAt(0).toUpperCase() + s.slice(1);
}
// « N enquête(s) » localisé
export function labelNbEnquetes(n) {
  return n + ' ' + (n > 1 ? t('res_surveys') : t('res_survey'));
}
